// Parsing SVG markup is slow on the TV, and a home screen has hundreds of icons, so each
// icon is parsed once and cloned after that.
const iconCache = {};
function icon(name, cls) {
  const key = name + '|' + (cls || '');
  if (!iconCache[key]) {
    const def = ICONS[name];
    const wrap = document.createElement('span');
    // Parsing through HTML is the most reliable way to build SVG on old browsers.
    wrap.innerHTML = '<svg class="icon' + (cls ? ' ' + cls : '') + '" viewBox="' + (def ? def[0] : '0 0 512 512') +
      '" xmlns="http://www.w3.org/2000/svg">' + (def ? def[1] : '') + '</svg>';
    iconCache[key] = wrap.firstChild;
  }
  return iconCache[key].cloneNode(true);
}
